BEGIN;
ALTER TABLE public.custia_characters ADD COLUMN IF NOT EXISTS age integer CHECK(age BETWEEN 18 AND 60), ADD COLUMN IF NOT EXISTS height numeric CHECK(height>0), ADD COLUMN IF NOT EXISTS weight numeric CHECK(weight>0), ADD COLUMN IF NOT EXISTS gender text DEFAULT 'Unspecified' CHECK(gender IN ('Male','Female','Unspecified')), ADD COLUMN IF NOT EXISTS quote text DEFAULT '', ADD COLUMN IF NOT EXISTS skill1 text DEFAULT '', ADD COLUMN IF NOT EXISTS skill2 text DEFAULT '', ADD COLUMN IF NOT EXISTS skill3 text DEFAULT '', ADD COLUMN IF NOT EXISTS skill4 text DEFAULT '', ADD COLUMN IF NOT EXISTS facebook text DEFAULT '', ADD COLUMN IF NOT EXISTS discord text DEFAULT '', ADD COLUMN IF NOT EXISTS rp text[] DEFAULT '{}' CHECK(rp <@ ARRAY['18 UP','20 UP','BL','HL','GL','FZ','NoL']::text[]);
CREATE TABLE IF NOT EXISTS public.custia_character_private(character_id uuid PRIMARY KEY REFERENCES public.custia_characters(id) ON DELETE CASCADE,real_name text NOT NULL DEFAULT '');
ALTER TABLE public.custia_character_private ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.custia_character_private FROM public,anon,authenticated;
GRANT SELECT,INSERT,UPDATE ON public.custia_character_private TO authenticated;
DROP POLICY IF EXISTS own_character_private ON public.custia_character_private;
CREATE POLICY own_character_private ON public.custia_character_private FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.custia_characters c WHERE c.id=character_id AND c.owner=auth.uid())) WITH CHECK(EXISTS(SELECT 1 FROM public.custia_characters c WHERE c.id=character_id AND c.owner=auth.uid()));
INSERT INTO public.custia_character_private SELECT id,name FROM public.custia_characters ON CONFLICT DO NOTHING;
UPDATE public.custia_characters SET name=coalesce(nullif(alias,''),'Unknown');
REVOKE UPDATE ON public.custia_characters FROM authenticated;
REVOKE UPDATE(number) ON public.custia_characters FROM authenticated;
GRANT INSERT(age,height,weight,gender,quote,skill1,skill2,skill3,skill4,facebook,discord,rp), UPDATE(age,height,weight,gender,quote,skill1,skill2,skill3,skill4,facebook,discord,rp) ON public.custia_characters TO authenticated;
CREATE OR REPLACE FUNCTION public.custia_limit_chars() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN
PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(new.owner::text,0));
IF (SELECT count(*) FROM public.custia_characters WHERE owner=new.owner)>=2 THEN RAISE EXCEPTION 'Character limit reached (2)'; END IF;
IF new.number IS NULL OR new.number !~ '^[0-9]{1,30}$' THEN RAISE EXCEPTION 'Number required'; END IF;
IF new.number ~ '^0*111$' THEN RAISE EXCEPTION 'Reserved number'; END IF;
RETURN new; END $$;
DROP TRIGGER IF EXISTS custia_limit_chars ON public.custia_characters;
CREATE TRIGGER custia_limit_chars BEFORE INSERT ON public.custia_characters FOR EACH ROW EXECUTE FUNCTION public.custia_limit_chars();
CREATE OR REPLACE FUNCTION public.custia_immutable_number() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$ BEGIN IF new.number IS DISTINCT FROM old.number THEN RAISE EXCEPTION 'Number is immutable'; END IF; RETURN new; END $$;
DROP TRIGGER IF EXISTS custia_immutable_number ON public.custia_characters;
CREATE TRIGGER custia_immutable_number BEFORE UPDATE ON public.custia_characters FOR EACH ROW EXECUTE FUNCTION public.custia_immutable_number();
GRANT DELETE ON public.custia_characters TO authenticated;
DROP POLICY IF EXISTS custia_manager_delete ON public.custia_characters;
CREATE POLICY custia_manager_delete ON public.custia_characters FOR DELETE TO authenticated USING(public.custia_staff_role() IN ('Manager','Special Manager'));
DROP POLICY IF EXISTS custia_portrait_delete ON storage.objects;
CREATE POLICY custia_portrait_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='custia-portraits' AND (storage.foldername(name))[1]=auth.uid()::text);
COMMIT;
NOTIFY pgrst,'reload schema';
